# Factorization of 39455
def factorize(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

print(f"39455 factorization: {factorize(39455)}")
print(f"94175 factorization: {factorize(94175)}")
